create table if not exists public.help_articles (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  route_pattern text,
  title text not null,
  purpose text not null,
  steps jsonb not null default '[]'::jsonb,
  common_problems jsonb not null default '[]'::jsonb,
  related_slugs text[] not null default '{}',
  keywords text[] not null default '{}',
  last_updated timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists idx_help_articles_slug on public.help_articles(slug);
create index if not exists idx_help_articles_route on public.help_articles(route_pattern);
grant select on public.help_articles to authenticated;
grant all on public.help_articles to service_role;
alter table public.help_articles enable row level security;
create policy "Help articles readable by authenticated users" on public.help_articles for select to authenticated using (true);
create policy "Admins manage help articles" on public.help_articles for all to authenticated using (public.has_role(auth.uid(), 'admin')) with check (public.has_role(auth.uid(), 'admin'));
create or replace function public.touch_help_article_updated()
returns trigger language plpgsql security definer set search_path = public as $$
begin new.last_updated := now(); return new; end $$;
drop trigger if exists trg_touch_help_article on public.help_articles;
create trigger trg_touch_help_article before update on public.help_articles for each row execute function public.touch_help_article_updated();

insert into public.help_articles (slug, route_pattern, title, purpose, steps, common_problems, related_slugs, keywords) values
('dashboard','/','Dashboard','Landing page after sign-in. Admins see director overview (revenue, jobs, engineer activity); engineers see only their own jobs for today.',
'[{"heading":"See today''s work","items":["Open the app — the Dashboard loads by default.","Look at Today''s Jobs for jobs scheduled today.","Click any job card to open its detail page."]},{"heading":"Get to other areas","items":["Use the left sidebar to jump to Jobs, Planner, Customers.","Press Cmd+K (Ctrl+K on Windows) for the command palette."]}]'::jsonb,
'[{"problem":"Dashboard looks empty","fix":"You may have no jobs assigned for today. Try Jobs in the sidebar."},{"problem":"I''m an engineer but I see admin content","fix":"Your role is set to admin. Ask an admin to change it in Settings → Team."}]'::jsonb,
array['jobs','planner'],array['home','overview','stats']),
('jobs','/jobs','Jobs','Central list of all jobs. Create, filter, bulk import and open jobs. References use the VFP- prefix.',
