'[{"problem":"Wrong category on a job","fix":"Category is immutable — archive it and create a new one."},{"problem":"Reference number skipped","fix":"Normal — a discarded draft can leave a gap."}]'::jsonb,
array['jobs.create','jobs.detail','planner','po-email-intake'],array['work order','ticket','vfp']),
('jobs.create','/jobs','Creating a job','Full walkthrough of the New Job dialog. Every field can be edited later except category.',
