'[{"problem":"Site dropdown is empty","fix":"Customer has no sites yet. Add one from the Customer detail page → Sites section."},{"problem":"I picked the wrong category","fix":"Category can''t change. Archive and recreate."}]'::jsonb,
array['jobs','jobs.detail','customers','sites'],array['new job','create','add']),
